const favorites=(()=>{try{return JSON.parse(localStorage.getItem('case-club.favorites')||'[]');}catch{return [];}})();
const grid=document.getElementById('concept-grid');
grid.innerHTML=window.CASE_THEMES.map((t,i)=>`<article class="concept-card" style="--tone:${t.tone};--accent:${t.accent}"><a class="concept-preview" href="legacy-play.html?theme=${t.id}&case=К001" aria-label="Открыть концепцию ${t.name}"><img src="previews/${t.id}.jpg" alt="${t.name}: ${t.tag}" width="1363" height="936" loading="${i<2?'eager':'lazy'}"><span class="preview-overlay"><span class="preview-open">Посмотреть вживую ${icon('arrow',16)}</span></span></a><div class="concept-heading"><div class="concept-title"><span class="concept-number">${String(i+1).padStart(2,'0')}</span><h3>${t.name}</h3></div><button class="favorite" type="button" data-favorite="${t.id}" aria-pressed="${favorites.includes(t.id)}">${favorites.includes(t.id)?'В избранном ✓':'В избранное +'}</button></div><div class="concept-tag"><i></i>${t.tag}</div><p class="concept-desc">${t.desc}</p><div class="concept-actions"><a class="open-link" href="legacy-play.html?theme=${t.id}&case=К001">Открыть прототип ${icon('arrow',15)}</a>${t.pick?`<span class="recommendation">${t.pick}</span>`:''}</div></article>`).join('');
document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favorite,at=favorites.indexOf(id);if(at>=0)favorites.splice(at,1);else favorites.push(id);b.setAttribute('aria-pressed',String(at<0));b.textContent=at<0?'В избранном ✓':'В избранное +';try{localStorage.setItem('case-club.favorites',JSON.stringify(favorites));}catch{}const toast=document.getElementById('studio-toast');toast.textContent=at<0?'Добавлено в избранное: '+window.CASE_THEMES.find(t=>t.id===id).name:'Убрано из избранного';toast.hidden=false;setTimeout(()=>toast.hidden=true,2400);});
